--keel:notx
-- Rollup audit_actor_daily of audit_entries, generated by keel's analytics/rollup. Do not edit; change the declaration and generate again.
CREATE TABLE IF NOT EXISTS keel_rollup_dirty (
    rollup text COLLATE "C" NOT NULL,
    tenant_key text COLLATE "C" NOT NULL,
    bucket timestamptz NOT NULL,
    xid xid8 NOT NULL,
    marked_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (rollup, tenant_key, bucket, xid)
);
CREATE INDEX IF NOT EXISTS keel_rollup_dirty_marked ON keel_rollup_dirty (marked_at);
CREATE TABLE IF NOT EXISTS keel_rollup_state (
    rollup text COLLATE "C" PRIMARY KEY,
    ready_at timestamptz NOT NULL
);
DELETE FROM keel_rollup_state WHERE rollup = 'audit_actor_daily';
DELETE FROM keel_rollup_dirty WHERE rollup = 'audit_actor_daily';
DO $keel$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_class WHERE oid = to_regclass('"audit_actor_daily"') AND obj_description(oid, 'pg_class') = 'keel rollup audit_actor_daily of audit_entries') THEN
        DROP TABLE "audit_actor_daily";
    END IF;
END
$keel$;
CREATE TABLE "audit_actor_daily" AS SELECT s."business_unit_id" AS "business_unit_id", s."organization_id" AS "organization_id", date_trunc('day', to_timestamp(s."timestamp"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = s."organization_id"), 'UTC'))) AS "bucket", s."principal_id" AS "principal_id", s."principal_type" AS "principal_type", s."resource" AS "resource", s."category" AS "category", count(*) AS "row_count", count(*) FILTER (WHERE (s."category" = 'Security' OR s."critical" IS TRUE OR s."operation" IN ('delete', 'export'))) AS "sensitive" FROM "audit_entries" s GROUP BY 1, 2, 3, 4, 5, 6, 7 WITH NO DATA;
COMMENT ON TABLE "audit_actor_daily" IS 'keel rollup audit_actor_daily of audit_entries';
ALTER TABLE "audit_actor_daily" ALTER COLUMN "business_unit_id" SET NOT NULL, ALTER COLUMN "organization_id" SET NOT NULL;
CREATE UNIQUE INDEX "audit_actor_daily_key" ON "audit_actor_daily" ("business_unit_id", "organization_id", "bucket", "principal_id", "principal_type", "resource", "category") NULLS NOT DISTINCT;
CREATE OR REPLACE FUNCTION keel_rollup_audit_actor_daily() RETURNS trigger LANGUAGE plpgsql AS $keel$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'audit_actor_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."timestamp"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_new n
        ON CONFLICT DO NOTHING;
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'audit_actor_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."timestamp"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM keel_old n
        ON CONFLICT DO NOTHING;
    ELSE
        INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid)
        SELECT DISTINCT 'audit_actor_daily', replace(replace(coalesce(n."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(n."organization_id"::text, ''), '\', '\\'), '/', '\/'), coalesce(date_trunc('day', to_timestamp(n."timestamp"), (coalesce((SELECT z."timezone" FROM "organizations" z WHERE z."id" = n."organization_id"), 'UTC'))), 'infinity'), pg_current_xact_id()
          FROM ((SELECT "business_unit_id", "organization_id", "timestamp", "resource", "operation", "category", "principal_type", "principal_id", "critical" FROM keel_old EXCEPT ALL SELECT "business_unit_id", "organization_id", "timestamp", "resource", "operation", "category", "principal_type", "principal_id", "critical" FROM keel_new) UNION ALL (SELECT "business_unit_id", "organization_id", "timestamp", "resource", "operation", "category", "principal_type", "principal_id", "critical" FROM keel_new EXCEPT ALL SELECT "business_unit_id", "organization_id", "timestamp", "resource", "operation", "category", "principal_type", "principal_id", "critical" FROM keel_old)) n
        ON CONFLICT DO NOTHING;
    END IF;
    RETURN NULL;
END
$keel$;
CREATE OR REPLACE TRIGGER "keel_rollup_audit_actor_daily_insert" AFTER INSERT ON "audit_entries" REFERENCING NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_audit_actor_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_audit_actor_daily_update" AFTER UPDATE ON "audit_entries" REFERENCING OLD TABLE AS keel_old NEW TABLE AS keel_new FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_audit_actor_daily();
CREATE OR REPLACE TRIGGER "keel_rollup_audit_actor_daily_delete" AFTER DELETE ON "audit_entries" REFERENCING OLD TABLE AS keel_old FOR EACH STATEMENT EXECUTE FUNCTION keel_rollup_audit_actor_daily();
--keel:split
WITH marked AS (INSERT INTO keel_rollup_dirty (rollup, tenant_key, bucket, xid) SELECT DISTINCT 'audit_actor_daily', replace(replace(coalesce(s."business_unit_id"::text, ''), '\', '\\'), '/', '\/') || '/' || replace(replace(coalesce(s."organization_id"::text, ''), '\', '\\'), '/', '\/'), '-infinity'::timestamptz, pg_current_xact_id() FROM "audit_entries" s ON CONFLICT DO NOTHING)
INSERT INTO keel_rollup_state (rollup, ready_at) VALUES ('audit_actor_daily', now()) ON CONFLICT (rollup) DO UPDATE SET ready_at = excluded.ready_at;
